    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, l;
    cin >> n >> l;

    vector<int> a(n), b(n), gaps1(n), gaps2(n);

    for (int &x : a) cin >> x;
    for (int &x : b) cin >> x;

    for (int i = 0; i < n - 1; ++i) {
        gaps1[i] = a[i + 1] - a[i];
        gaps2[i] = b[i + 1] - b[i];
    }

    gaps1[n - 1] = l - a[n - 1] + a[0];
    gaps2[n - 1] = l - b[n - 1] + b[0];

    vector<int> doubled = gaps1;
    doubled.insert(doubled.end(), gaps1.begin(), gaps1.end());

    bool found = false;

    for (int start = 0; start < n && !found; ++start) {
        found = true;
        for (int i = 0; i < n; ++i) {
            if (doubled[start + i] != gaps2[i]) {
                found = false;
                break;
            }
        }
    }

    cout << (found ? "YES\n" : "NO\n");
    return 0;
}

